using System.Globalization;
using System.Text;

namespace Yamlet.App.Services;

/// <summary>One dynamic variable's metadata, used to drive autocomplete and hover hints.</summary>
public sealed record DynamicVariable(string Name, string Description, string Example);

/// <summary>
/// Postman-style dynamic variables (<c>$guid</c>, <c>$timestamp</c>, <c>$random*</c>, …)
/// generated by our own logic — no external faker dependency. A <c>{{$name}}</c>
/// placeholder resolves to a freshly generated value each time it is used, so two
/// occurrences in the same request produce independent values (matching Postman).
/// <see cref="VariableResolver"/> falls back here when a placeholder is not a user
/// variable; the editor offers the <see cref="All"/> catalog for autocomplete.
/// </summary>
public static class DynamicVariables
{
    private static Random Rng => Random.Shared;

    /// <summary>The full catalog, in display order, for autocomplete and hints.</summary>
    public static IReadOnlyList<DynamicVariable> All { get; }

    private static readonly Dictionary<string, Func<string>> Generators;

    /// <summary>True if <paramref name="name"/> (placeholder body, e.g. <c>$guid</c>) is a known dynamic variable.</summary>
    public static bool IsDynamic(string? name) =>
        !string.IsNullOrEmpty(name) && Generators.ContainsKey(name.Trim());

    /// <summary>Generates a value for a dynamic variable, or returns false if the name is unknown.</summary>
    public static bool TryGenerate(string? name, out string value)
    {
        value = string.Empty;
        if (string.IsNullOrEmpty(name) || !Generators.TryGetValue(name.Trim(), out var gen))
        {
            return false;
        }

        try
        {
            value = gen();
            return true;
        }
        catch
        {
            value = string.Empty;
            return false;
        }
    }

    /// <summary>Looks up the catalog entry for a name, or null.</summary>
    public static DynamicVariable? Find(string? name) =>
        string.IsNullOrEmpty(name) ? null : _catalog.GetValueOrDefault(name.Trim());

    private static readonly Dictionary<string, DynamicVariable> _catalog;

    static DynamicVariables()
    {
        Generators = Definitions.ToDictionary(d => d.Name, d => d.Gen, StringComparer.OrdinalIgnoreCase);
        All = Definitions.Select(d => new DynamicVariable(d.Name, d.Description, Example(d.Gen))).ToList();
        _catalog = All.ToDictionary(d => d.Name, StringComparer.OrdinalIgnoreCase);
    }

    private static string Example(Func<string> gen)
    {
        try
        {
            var sample = gen();
            return sample.Length > 48 ? sample[..48] + "…" : sample;
        }
        catch
        {
            return string.Empty;
        }
    }

