    // ---- Helpers -------------------------------------------------------------

    private static string Pick(string[] pool) => pool[Rng.Next(pool.Length)];

    private static string RandomString(string alphabet, int length) =>
        new(Enumerable.Range(0, length).Select(_ => alphabet[Rng.Next(alphabet.Length)]).ToArray());

    private static string RandomIPv6() =>
        string.Join(":", Enumerable.Range(0, 8).Select(_ => Rng.Next(0x10000).ToString("x4", CultureInfo.InvariantCulture)));

    private static string RandomWords(int count) =>
        Capitalize(string.Join(" ", Enumerable.Range(0, count).Select(_ => Pick(WordPool))));

    private static string LoremWordsN(int count) =>
        string.Join(" ", Enumerable.Range(0, count).Select(_ => Pick(LoremWords)));

    private static string LoremSentence()
    {
        var count = Rng.Next(4, 10);
        return Capitalize(LoremWordsN(count)) + ".";
    }

    private static string LoremParagraph() =>
        string.Join(" ", Enumerable.Range(0, Rng.Next(3, 7)).Select(_ => LoremSentence()));

    private static string Capitalize(string text) =>
        string.IsNullOrEmpty(text) ? text : char.ToUpperInvariant(text[0]) + text[1..];
